<script>
  // === Menu ===
  function toggleMenu() {
    var dropdown = document.getElementById('vizMenuDropdown');
    if (dropdown) dropdown.classList.toggle('open');
  }
  document.addEventListener('click', function(e) {
    if (!e.target.closest('.viz-menu')) {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.remove('open');
    }
  });
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.remove('open');
    }
  });

  // === Theme ===
  var savedTheme = localStorage.getItem('viz-theme');
  var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
  function applyTheme(t) {
    document.documentElement.className = 'theme-' + t;
    document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
    document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
    localStorage.setItem('viz-theme', t);
    currentTheme = t;
    if (typeof onThemeChange === 'function') onThemeChange();
  }
  function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
  applyTheme(currentTheme);

  // === Scroll Reveal ===
  document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
  var revealObserver = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); }
    });
  }, { threshold: 0.1 });
  document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

  // === Download PNG ===
  async function downloadImage() {
    var menu = document.querySelector('.viz-menu');
    menu.style.display = 'none';
    try {
      var url = await htmlToImage.toPng(document.body, {
        quality: 1, pixelRatio: 2,
        filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
      });
      var a = document.createElement('a');
      a.href = url;
      a.download = 'imf-weo-poster-2024-2026.png';
      a.click();
    } catch(e) { console.error('Download failed:', e); }
    menu.style.display = '';
  }

  // === Charts ===
  var chartsBuilt = false;

  function getChartColors() {
    var isDark = document.documentElement.classList.contains('theme-dark');
    return {
      text: isDark ? '#EDEDED' : '#0f172a',
      textSecondary: isDark ? '#888888' : '#475569',
      gridColor: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.05)',
      surface: isDark ? '#141414' : '#FFFFFF',
      accent: isDark ? '#60a5fa' : '#002244',
      warning: '#D97706',
      bandFill: isDark ? 'rgba(59,130,246,0.06)' : 'rgba(0,34,68,0.05)',
      prePandemicLine: isDark ? 'rgba(245,158,11,0.6)' : 'rgba(217,119,6,0.55)',
    };
  }

  function resetCanvas(id) {
    var old = document.getElementById(id);
    if (!old) return null;
    var parent = old.parentNode;
    var canvas = document.createElement('canvas');
    canvas.id = id;
    parent.replaceChild(canvas, old);
    return canvas;
  }

  function buildCharts() {
    if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
    if (chartsBuilt) return;

    var c = getChartColors();

    // ── GROWTH CHART ──────────────────────────────────────────────────────
    var growthCanvas = resetCanvas('growthChart');
    if (growthCanvas) {
      growthCanvas.setAttribute('role', 'img');
      growthCanvas.setAttribute('aria-label', 'Line chart showing IMF global growth projections 3.0-3.3% across 8 WEO editions');

      var growthLabels = ['Jul 2024', 'Oct 2024', 'Jan 2025', 'Apr 2025', 'Jul 2025', 'Oct 2025', 'Jan 2026', 'Apr 2026'];
      // Actual WEO data points: using the projections for the upcoming year from each edition
      var growthData   = [3.3,        3.3,        3.3,        3.1,        3.0,        3.1,        3.3,        3.1];
      // Pre-pandemic average reference line
      var prePandemicData = [3.8, 3.8, 3.8, 3.8, 3.8, 3.8, 3.8, 3.8];
      // Band fill upper (3.3) and lower (3.0)
      var bandUpper = [3.3, 3.3, 3.3, 3.3, 3.3, 3.3, 3.3, 3.3];
      var bandLower = [3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0];

      ChartManager.safeInit('growthChart', {
        type: 'line',
        data: {
          labels: growthLabels,
          datasets: [
            {
              label: 'Band Upper (3.3%)',
              data: bandUpper,
              borderColor: 'transparent',
              backgroundColor: c.bandFill,
              fill: '+1',
              pointRadius: 0,
              tension: 0.3,
              order: 3,
            },
            {
              label: 'Band Lower (3.0%)',
              data: bandLower,
              borderColor: 'transparent',
              backgroundColor: c.bandFill,
              fill: false,
              pointRadius: 0,
              tension: 0.3,
              order: 4,
            },
            {
              label: 'Pre-Pandemic Average (~3.8%)',
              data: prePandemicData,
              borderColor: c.prePandemicLine,
              backgroundColor: 'transparent',
              borderWidth: 1.5,
              borderDash: [6, 4],
              pointRadius: 0,
              tension: 0,
              order: 2,
            },
            {
              label: 'IMF Projected Growth (%)',
              data: growthData,
              borderColor: c.accent,
              backgroundColor: c.accent,
              borderWidth: 2.5,
