file.content:
      height: 200px;
      position: relative;
      margin-top: 12px;
    }
    .inflation-note {
      background: rgba(0,34,68,0.05);
      border-left: 3px solid #D97706;
      border-radius: 0 6px 6px 0;
      padding: 10px 14px;
      margin-top: 12px;
      font-size: 11.5px;
      color: var(--text-secondary);
      line-height: 1.5;
    }
    html.theme-dark .inflation-note {
      background: rgba(245,158,11,0.06);
    }

    /* === POLICY TIMELINE === */
    .policy-section {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 22px 24px;
    }
    .policy-timeline {
      display: flex;
      gap: 0;
      margin-top: 16px;
      position: relative;
    }
    .policy-timeline::before {
      content: '';
      position: absolute;
      top: 22px;
      left: 20px;
      right: 20px;
      height: 2px;
      background: linear-gradient(90deg,
        #002244 0%,
        #1a4a8a 25%,
        #2563eb 50%,
        #D97706 75%,
        #B45309 100%
      );
      z-index: 0;
    }
    .policy-step {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      position: relative;
      z-index: 1;
      padding: 0 4px;
    }
    .policy-dot {
      width: 16px; height: 16px;
      border-radius: 50%;
      background: var(--surface);
      border: 2.5px solid #002244;
      margin-bottom: 10px;
      position: relative;
      z-index: 2;
      flex-shrink: 0;
      transition: transform 0.2s;
    }
    html.theme-dark .policy-dot { background: #141414; border-color: #3b82f6; }
    .policy-step:nth-child(4) .policy-dot,
    .policy-step:nth-child(5) .policy-dot,
    .policy-step:nth-child(6) .policy-dot {
      border-color: #D97706;
    }
    html.theme-dark .policy-step:nth-child(4) .policy-dot,
    html.theme-dark .policy-step:nth-child(5) .policy-dot,
    html.theme-dark .policy-step:nth-child(6) .policy-dot {
      border-color: #F59E0B;
    }
    .policy-step:hover .policy-dot { transform: scale(1.3); }
    .policy-date {
      font-size: 10px;
      font-weight: 700;
      color: var(--text-secondary);
      text-align: center;
      margin-bottom: 5px;
      letter-spacing: 0.04em;
    }
    .policy-text {
      font-size: 10.5px;
      color: var(--text);
      text-align: center;
      line-height: 1.45;
      font-weight: 500;
    }
    .policy-text em {
      font-style: normal;
      color: #D97706;
      font-weight: 600;
    }
    html.theme-dark .policy-text em { color: #F59E0B; }

    /* === THEMES SECTION === */
    .themes-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 10px;
      margin-top: 12px;
    }
    .theme-chip {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 12px 14px;
      font-size: 11.5px;
      color: var(--text);
      line-height: 1.4;
      font-weight: 500;
      display: flex;
      align-items: flex-start;
      gap: 8px;
      transition: box-shadow 0.2s;
    }
    .theme-chip:hover {
      box-shadow: 0 0 0 1px rgba(0,34,68,0.12), 0 4px 10px rgba(0,0,0,0.06);
    }
    .theme-chip-dot {
      width: 6px; height: 6px;
      border-radius: 50%;
      background: #002244;
      flex-shrink: 0;
      margin-top: 4px;
    }
    html.theme-dark .theme-chip-dot { background: #60a5fa; }

    /* FOOTER */
    .poster-footer {
      padding: 14px 48px;
      border-top: 1px solid var(--border);
      display: flex;
      justify-content: space-between;
      align-items: center;
      background: var(--surface);
    }
    .footer-sources {
      font-size: 10px;
      color: var(--text-secondary);
      line-height: 1.6;
    }
    .footer-imf {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .imf-badge {
      background: #002244;
      color: white;
      font-size: 11px;
      font-weight: 700;
      padding: 5px 12px;
      border-radius: 5px;
      letter-spacing: 0.04em;
    }
    .footer-note {
      font-size: 10px;
      color: var(--text-secondary);
      text-align: right;
      line-height: 1.5;
    }

    @media (max-width: 375px) {
      body { overflow-x: hidden; }
    }
  </style>
</head>
