<main id="main-content" role="main">
<div class="poster-wrapper">

  <!-- ═══════════════════════════════════════════ HEADER ═══════════════════ -->
  <header class="poster-header" role="banner">
    <div class="header-eyebrow animate">IMF–World Bank Annual Meetings Research Symposium · April 2026</div>
    <h1 class="animate delay-1">Global Economy in the Shadow of War:<br>IMF World Economic Outlook Trends 2024–2026</h1>
    <p class="header-subtitle animate delay-2">
      A synthesis of eight WEO editions tracking the trajectory of global growth, inflation, and evolving policy priorities amid mounting geopolitical uncertainty. Growth projections have remained in a narrow band of persistent mediocrity while downside risks intensify.
    </p>
    <div class="header-meta animate delay-3">
      <span class="header-badge">8 WEO Editions · Jul 2024 – Apr 2026</span>
      <span class="header-badge">Global Growth Band: 3.0 – 3.3%</span>
      <span class="header-badge warning">
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="display:inline;vertical-align:middle;margin-right:3px"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
        Risk Balance: Tilted to the Downside
      </span>
    </div>
  </header>

  <!-- ═══════════════════════════════════════════ METRICS STRIP ═══════════ -->
  <section aria-label="Key metrics" class="metrics-strip animate delay-4">
    <div class="metric-item">
      <div class="metric-value" data-count="3" data-suffix=".0%">3.0%</div>
      <div class="metric-label">Global Growth 2025<br>(WEO Jul 2025)</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">3.3%</div>
      <div class="metric-label">Global Growth 2026<br>(WEO Jan 2026)</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">3.2%</div>
      <div class="metric-label">Global Growth 2027<br>(WEO Jan 2026)</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">~3.8%</div>
      <div class="metric-label">Pre-Pandemic Average<br>(Historical baseline)</div>
    </div>
    <div class="metric-item">
      <div class="metric-value warning">−0.6pp</div>
      <div class="metric-label">Growth Gap vs.<br>Historical Average</div>
    </div>
    <div class="metric-item">
      <div class="metric-value warning">8/8</div>
      <div class="metric-label">Editions with downside-<br>tilted risk balance</div>
    </div>
  </section>

  <!-- ═══════════════════════════════════════════ BODY ═══════════════════ -->
  <div class="poster-body">

    <!-- RISK CALLOUT BANNER -->
    <div class="risk-callout animate delay-5" role="note" aria-label="Key finding">
      <div class="risk-icon">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#F97316" stroke-width="2.5">
          <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/>
          <line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>
        </svg>
      </div>
      <div class="risk-callout-text">
        <h3>Consistent Finding Across All 8 Editions</h3>
        <p>The balance of risks is <strong style="color:#FED7AA">persistently and consistently tilted to the downside</strong> — global growth is not collapsing, but neither is it recovering. The risk of further deterioration outweighs prospects for upside surprises in every reviewed edition.</p>
      </div>
    </div>

    <!-- SECTION 1: GROWTH TRAJECTORY (CENTERPIECE) -->
    <section class="growth-section" aria-labelledby="growth-heading" data-reveal>
      <div class="section-label">Section 1 — Visual Centerpiece</div>
      <div class="growth-chart-card">
        <div class="growth-chart-header">
          <div class="growth-chart-header-left">
            <div class="section-label" style="margin-bottom:4px">Global Growth Projections</div>
            <h2 id="growth-heading">A Narrow Band of Persistent Mediocrity</h2>
            <p style="font-size:12px;color:var(--text-secondary);margin-top:4px">IMF WEO headline global GDP growth forecasts across eight editions, Jul 2024 – Apr 2026</p>
          </div>
          <div class="growth-legend">
            <div class="legend-item">
              <div class="legend-dot" style="background:#002244"></div>
              <span>Projected growth</span>
            </div>
            <div class="legend-item">
              <div class="legend-dot" style="background:rgba(217,119,6,0.5);border:1.5px dashed #D97706"></div>
              <span>Pre-pandemic avg ~3.8%</span>
            </div>
            <div class="legend-item">
              <div class="legend-dot" style="background:rgba(0,34,68,0.12);border-radius:2px;width:16px;height:10px"></div>
              <span>3.0–3.3% band</span>
            </div>
          </div>
        </div>
        <div class="chart-container-main">
          <canvas id="growthChart" role="img" aria-label="Line chart showing IMF global growth projections ranging from 3.0% to 3.3% across 8 WEO editions from July 2024 to April 2026, well below the pre-pandemic average of 3.8%"></canvas>
        </div>
        <div class="weo-editions" style="margin-top:14px">
          <span class="weo-chip">Jul '24: Sticky Spot</span>
          <span class="weo-chip">Oct '24: Policy Pivot</span>
          <span class="weo-chip">Jan '25: Divergent</span>
          <span class="weo-chip">Apr '25: Critical Juncture</span>
          <span class="weo-chip">Jul '25: Tenuous Resilience</span>
          <span class="weo-chip">Oct '25: Prospects Dim</span>
          <span class="weo-chip">Jan '26: Steady amid Divergence</span>
          <span class="weo-chip current">Apr '26: Shadow of War ▲</span>
        </div>
